```json
{
  "map": true,
  "subject": {
    "columns": ["protein_id"],
    "resolver": "pharos_protein_gene",
    "category": "biolink:Gene",
    "name_column": "protein_id"
  },
  "object": {
    "columns": ["mondoid"],
    "resolver": "curie",
    "category": "biolink:Disease",
    "name_column": "name"
  },
  "predicate": "biolink:gene_associated_with_condition",
  "association_category": "biolink:GeneToDiseaseAssociation",
  "knowledge_level": "statistical_association",
  "agent_type": "text_mining_agent",
  "primary_knowledge_source": "infores:diseases",
  "qualifiers": {},
  "edge_properties": ["evidence", "zscore", "conf", "dtype", "did"],
  "keep_if": {
    "column": "mondoid",
    "matches": "^(MONDO:.+)$",
    "reason": "Rows without a MONDO id have no grounded Biolink Disease identifier; the DOID and AmyCo identifiers in this table are not in the release's disease identifier list, so these rows are kept as gaps of the gene rather than given an object."
  },
  "split_by": "dtype",
  "by_value": {
    "JensenLab Text Mining": {
      "knowledge_level": "statistical_association",
      "agent_type": "text_mining_agent"
    },
    "JensenLab Experiment TIGA": {
      "knowledge_level": "statistical_association",
      "agent_type": "data_analysis_pipeline"
    },
    "JensenLab Knowledge MedlinePlus": {
      "knowledge_level": "knowledge_assertion",
      "agent_type": "manual_agent"
    },
    "JensenLab Knowledge UniProtKB-KW": {
      "knowledge_level": "knowledge_assertion",
      "agent_type": "manual_agent"
    },
    "JensenLab Knowledge AmyCo": {
      "knowledge_level": "knowledge_assertion",
      "agent_type": "manual_agent"
    }
  },
  "notes": "Object is taken only from mondoid, which is the grounded Biolink Disease identifier. The did fallback was removed because its DOID values (and AmyCo-prefixed values) failed the release identifier check. Rows with empty mondoid are recorded as gaps of the gene via keep_if, not dropped. Predicate gene_associated_with_condition is the most specific gene-disease predicate in Biolink 4.4.3. Knowledge level and agent differ by dtype: text mining is co-occurrence-based; TIGA is a computed score from a pipeline; MedlinePlus, UniProtKB keyword and AmyCo are curated assertions. Primary source is infores:diseases for all rows because the upstream resource is not separately identified; dtype keeps the distinction. No score threshold is applied; conf and zscore are carried as edge properties."
}
